from math import gcd
from collections import Counter


class Solution:
    def countPairs(self, nums: List[int], k: int) -> int:
        cnt = Counter(gcd(x, k) for x in nums)
        gs = list(cnt)
        ans = 0
        for i, g1 in enumerate(gs):
            for g2 in gs[i:]:
                if g1 * g2 % k == 0:
                    if g1 == g2:
                        ans += cnt[g1] * (cnt[g1] - 1) // 2
                    else:
                        ans += cnt[g1] * cnt[g2]
        return ans

