class Solution {
public:
    long long countPairs(vector<int>& nums, int k) {
        unordered_map<int, long long> cnt;
        for (int x : nums) cnt[gcd(x, k)]++;
        vector<pair<int, long long>> gs(cnt.begin(), cnt.end());
        long long ans = 0;
        for (int i = 0; i < (int)gs.size(); i++) {
            for (int j = i; j < (int)gs.size(); j++) {
                long long prod = (long long)gs[i].first * gs[j].first;
                if (prod % k) continue;
                ans += i == j ? gs[i].second * (gs[i].second - 1) / 2
                              : gs[i].second * gs[j].second;
            }
        }
        return ans;
    }
};

