class Solution {
    public long countPairs(int[] nums, int k) {
        Map<Integer, Long> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(gcd(x, k), 1L, Long::sum);
        List<Map.Entry<Integer, Long>> gs = new ArrayList<>(cnt.entrySet());
        long ans = 0;
        for (int i = 0; i < gs.size(); i++) {
            for (int j = i; j < gs.size(); j++) {
                long prod = (long) gs.get(i).getKey() * gs.get(j).getKey();
                if (prod % k != 0) continue;
                ans += i == j
                        ? gs.get(i).getValue() * (gs.get(i).getValue() - 1) / 2
                        : gs.get(i).getValue() * gs.get(j).getValue();
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

