    let ans = 0;
    for (let i = 0; i < gs.length; i++) {
        for (let j = i; j < gs.length; j++) {
            if (gs[i][0] * gs[j][0] % k !== 0) continue;
            ans += i === j ? gs[i][1] * (gs[i][1] - 1) / 2 : gs[i][1] * gs[j][1];
        }
    }
    return ans;
};

