from math import gcd
from collections import defaultdict


class Solution:
    def countPairs(self, nums: List[int], k: int) -> int:
        cnt = defaultdict(int)
        ans = 0
        for x in nums:
            ans += cnt[k // gcd(x, k)]
            d = 1
            while d * d <= x:
                if x % d == 0:
                    cnt[d] += 1
                    if d * d != x:
                        cnt[x // d] += 1
                d += 1
        return ans

