class Solution {
    public long countPairs(int[] nums, int k) {
        Map<Integer, Long> cnt = new HashMap<>();
        long ans = 0;
        for (int x : nums) {
            ans += cnt.getOrDefault(k / gcd(x, k), 0L);
            for (int d = 1; (long) d * d <= x; d++) {
                if (x % d == 0) {
                    cnt.merge(d, 1L, Long::sum);
                    if (d * d != x) cnt.merge(x / d, 1L, Long::sum);
                }
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

